WITH roster AS ( SELECT DISTINCT a.expert_id AS agent_id FROM hive.care.expert_performance_metrics a WHERE CAST(a."date" AS DATE) BETWEEN DATE '2026-06-20' AND DATE '2026-07-31' AND LOWER(a.icp_client) IN ( 'pss-verizon','pss-at&t','mob-verizon','mob-at&t' ) ) SELECT b.expert_id AS agent_id, CAST(date_add('day', 4, date_trunc('week', CAST(b."date" AS DATE))) AS DATE) AS week_ending, 'all' AS call_type, b.template_questions_name AS scorecard_name, b.behavior_name AS behavior, SUM(COALESCE(CAST(b.score AS DOUBLE), 0.0)) AS numerator, SUM(COALESCE(CAST(b.opportunity AS DOUBLE), 0.0)) AS denominator, CASE WHEN SUM(COALESCE(CAST(b.opportunity AS DOUBLE), 0.0)) = 0 THEN NULL ELSE SUM(COALESCE(CAST(b.score AS DOUBLE), 0.0)) / SUM(COALESCE(CAST(b.opportunity AS DOUBLE), 0.0)) END AS calc FROM hive.care.l3_asurion_observe_behaviors_scores b JOIN roster r ON r.agent_id = b.expert_id WHERE CAST(b."date" AS DATE) BETWEEN DATE '2026-06-20' AND DATE '2026-07-31' AND b.template_questions_name IN ( 'HEROES Auto Scorecard','HEROES Auto QA Reporting - VZW','Customer Sentiment Scorecard V1' ) GROUP BY 1, 2, 3, 4, 5
